FENCE_ASSETS=['assets/game/locations/overworld/fences/profile.json']+['assets/game/locations/overworld/fences/'+side+'_v1.png'+suffix for side in ['post','rail','depth'] for suffix in ['', '.import']]

def collect(folder,phase):
